3091	/**
3092	 * Every ABSOLUTE executable path a unit's Exec* directives will try to run.
3093	 *
3094	 * Defensive by design, because a unit file is untrusted input from another
3095	 * machine:
3096	 *   - `ExecStart=-/path`  the `-` (ignore failure), `@` (argv[0] override),
3097	 *     `+` (full privileges), `!` / `!!` (no-setuid variants) prefixes may appear
3098	 *     in any order and combination and are stripped before the path is read;
3099	 *   - quoted paths (`ExecStart="/opt/my app/bin/run" --flag`) are unquoted;
3100	 *   - an EMPTY assignment (`ExecStart=`) is systemd's list-reset and is skipped;
3101	 *   - a bare command (`ExecStart=node server.js`) is resolved from PATH by
3102	 *     systemd itself, so it is deliberately IGNORED — we cannot check it and
3103	 *     guessing would be worse than silence;
3104	 *   - a path carrying a `%` specifier (`/usr/bin/%i`) can only be resolved by
3105	 *     systemd, so it is skipped rather than mis-reported. It also would not pass
3106	 *     PATH_RE, which is what keeps every value here shell-inert.
3107	 */
3108	export function parseUnitExecPaths(text: string): UnitExecRef[] {
3109	  const out: UnitExecRef[] = [];
3110	  const seen = new Set<string>();
3111	  for (const line of unfoldUnitLines(text)) {
3112	    const m = /^(ExecStart|ExecStartPre|ExecStartPost)\s*=\s*(.*)$/.exec(line);
3113	    if (!m) continue;
3114	    let rhs = m[2].trim();
3115	    if (!rhs) continue; // `ExecStart=` — a list reset, not a command
3116	    rhs = rhs.replace(/^[-@+!]+\s*/, "").trim();
3117	    if (!rhs) continue;
3118	    let exe: string;
3119	    const q = rhs[0];
3120	    if (q === '"' || q === "'") {
3121	      const end = rhs.indexOf(q, 1);
3122	      exe = end > 0 ? rhs.slice(1, end) : rhs.slice(1);
3123	    } else {
3124	      exe = rhs.split(/\s+/)[0] ?? "";
3125	    }
3126	    exe = exe.trim();
3127	    if (!exe.startsWith("/")) continue; // PATH-resolved — not ours to check
3128	    if (!validPath(exe)) continue; // %-specifiers and odd charsets: unresolvable here
3129	    const key = `${m[1]}|${exe}`;
3130	    if (seen.has(key) || out.length >= 12) continue;
3131	    seen.add(key);
3132	    out.push({ directive: m[1], path: exe });
3133	  }
3134	  return out;
3135	}
