/**
 * Every ABSOLUTE `EnvironmentFile=` a unit reads its config/secrets from.
 *
 * WHY: a unit that reads its secrets from `EnvironmentFile=/etc/myapp/env` (a path
 * outside any selected copy dir) is happily enabled while that file never comes
 * across, so the service boots UNCONFIGURED. These have to be pulled the same way
 * `preflightUnitExecs` pulls a missing interpreter.
 *
 * Same defensive parsing as the Exec* directives:
 *   - a leading `-` means "optional" (systemd ignores it if absent) and is stripped;
 *   - quoted paths are unquoted;
 *   - an empty assignment (`EnvironmentFile=`) is systemd's list-reset and skipped;
 *   - only ABSOLUTE, PATH_RE-valid paths are returned — a `%`-specifier path is
 *     unresolvable here and would not pass validPath, which keeps it shell-inert;
 *   - multiple `EnvironmentFile=` lines per unit are all returned.
 */
export function parseUnitEnvironmentFiles(text: string): { path: string; optional: boolean }[] {
  const out: { path: string; optional: boolean }[] = [];
  const seen = new Set<string>();
  for (const line of unfoldUnitLines(text)) {
    const m = /^EnvironmentFile\s*=\s*(.*)$/.exec(line);
    if (!m) continue;
    let rhs = m[1].trim();
    if (!rhs) continue; // `EnvironmentFile=` — a list reset, not a file
    let optional = false;
    if (rhs[0] === "-") {
      optional = true;
      rhs = rhs.slice(1).trim();
    }
    let file: string;
    const q = rhs[0];
    if (q === '"' || q === "'") {
      const end = rhs.indexOf(q, 1);
      file = end > 0 ? rhs.slice(1, end) : rhs.slice(1);
    } else {
      file = rhs.split(/\s+/)[0] ?? "";
    }
    file = file.trim();
    if (!file.startsWith("/")) continue; // relative to a %-dir — not ours to resolve
    if (!validPath(file)) continue; // %-specifiers / odd charsets: unresolvable here
    if (seen.has(file) || out.length >= 12) continue;
    seen.add(file);
    out.push({ path: file, optional });
  }
  return out;
}

/**
 * The `User=` / `Group=` a unit runs as, or "" when unset. Used to make sure the
 * ACCOUNT a migrated unit runs under exists on the target — a `User=appsvc` with
 * a uid<1000 is below the global user-recreation filter (which is deliberately
 * kept at uid≥1000), so the unit would fail to start and its copied files would
 * show a bare uid. Only the accounts referenced by MIGRATED units are recreated
 * from here; a `%`-specifier or numeric value is left for the existing loop.
 */
export function parseUnitUserGroup(text: string): { user: string; group: string } {
  let user = "";
  let group = "";
  for (const line of unfoldUnitLines(text)) {
    const mu = /^User\s*=\s*(.*)$/.exec(line);
    if (mu) {
      const v = mu[1].trim().replace(/^["']|["']$/g, "").trim();
      if (v) user = v;
      continue;
    }
    const mg = /^Group\s*=\s*(.*)$/.exec(line);
    if (mg) {
      const v = mg[1].trim().replace(/^["']|["']$/g, "").trim();
      if (v) group = v;
    }
  }
  return { user, group };
}

