/**
 * Make sure the ACCOUNT a migrated unit runs as exists on the target.
 *
 * The global user-recreation loop (step 5e) is deliberately filtered to uid≥1000
 * — real login users, not system daemons. But a `User=appsvc` unit whose account
 * has uid<1000 is below that filter, so it is never recreated: the unit then
 * fails to start and its copied files show a bare uid. Rather than lower the
 * global filter (which would drag in the OS's own daemon accounts), derive the
 * needed accounts from the unit actually migrated, and create only those, as
 * SYSTEM accounts (`useradd -r`, no login, no password). Idempotent: an account
 * that already exists is left untouched. Every value is validated before it
 * reaches a command.
 */
async function ensureUnitAccounts(opts: { conn: Client; unitFile: string }): Promise<string[]> {
  const { conn, unitFile } = opts;
  const made: string[] = [];
  if (!validPath(unitFile)) return made;
  const text = (await sh(conn, `cat ${unitFile} 2>/dev/null`, SETUP_TIMEOUT_MS)).stdout;
  const { user, group } = parseUnitUserGroup(text);
  const groupOk = !!group && USER_RE.test(group);
  if (groupOk) {
    if (!(await shOk(conn, `getent group ${group} >/dev/null 2>&1`))) {
      const r = await sh(conn, `groupadd -r ${group} >/dev/null 2>&1`);
      if (r.code === 0) made.push(`group ${group}`);
    }
  }
  // A numeric User= (systemd allows it) is not a name to create — it is handled
  // by the numeric-id ownership the files already carry. Only NAMED accounts here.
  if (user && USER_RE.test(user)) {
    if (!(await shOk(conn, `getent passwd ${user} >/dev/null 2>&1`))) {
      const gflag = groupOk ? `-g ${group} ` : "";
      const r = await sh(conn, `useradd -r -M -s ${NOLOGIN} ${gflag}${user} >/dev/null 2>&1`);
      if (r.code === 0) made.push(`user ${user}`);
    }
  }
  return made;
}

