// ---- 11a. systemd TIMERS (copy .timer + backing .service → enable) ------
// Detection only ever listed `.service` units, so timer-driven backups and
// maintenance simply vanished in a migration. Bring across BOTH the `.timer`
// (which owns the schedule) and its backing `.service` (the job it fires),
// recreate the service's account, PRE-FLIGHT the service's execs like any
// other unit, then `enable --now` the TIMER so it fires on schedule and
// survives reboots. Reuses the migrated-unit machinery throughout.
if (plan.timers.length) {
  await report(91, "Re-enabling timers…", `Re-enabling up to ${plan.timers.length} scheduled-task timer(s) from the old server.`);
  for (const tname of plan.timers) {
    if (!SVCNAME_RE.test(tname)) continue;
    const timerUnit = `/etc/systemd/system/${tname}.timer`;
    const svcUnit = `/etc/systemd/system/${tname}.service`;

    // 1. The .timer itself. As with services, a failed pull usually means a
    //    distro timer (in /lib/systemd/system) the target may already provide.
    const rt = await execRemote(conn, rsyncPull(timerUnit, "/etc/systemd/system"), SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
    if (rt.code !== 0) {
      const activeHere = await shOk(conn, `systemctl is-active --quiet ${tname}.timer`);
      const presentHere =
        activeHere || (await shOk(conn, `systemctl list-unit-files ${tname}.timer --no-legend 2>/dev/null | grep -q .`));
      if (activeHere) push({ step: `Timer ${tname}`, status: "running", detail: `this server already provides and runs ${tname}.timer — nothing to move` });
      else if (presentHere) push({ step: `Timer ${tname}`, status: "copied", detail: `${tname}.timer is installed on this server but not active. If your setup needs it: systemctl enable --now ${tname}.timer` });
      else push({ step: `Timer ${tname}`, status: "copied", detail: `${tname}.timer ran on the old server but its unit is not a plain /etc/systemd/system file, so it was NOT migrated — recreate it by hand if you still need that schedule` });
      continue;
    }

    // 2. The backing .service the timer triggers. A timer with nothing to run
    //    would just fire and fail — name that honestly.
    const rs = await execRemote(conn, rsyncPull(svcUnit, "/etc/systemd/system"), SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
    if (rs.code !== 0) {
      push({
        step: `Timer ${tname} was NOT started`,
        status: "failed",
        detail: `its schedule (${tname}.timer) copied across, but the task it runs (${tname}.service) is not a plain /etc/systemd/system file on the old server and is not on this one — the timer would fire with nothing to run. Recreate ${tname}.service, then: systemctl enable --now ${tname}.timer`,
      });
      continue;
    }

    // 3. Recreate the backing service's account (uid<1000 included).
    const tacct = await ensureUnitAccounts({ conn, unitFile: svcUnit });
    if (tacct.length) {
      push({ step: `Prepare ${tname} account(s)`, status: "running", detail: `created ${tacct.join(", ")} on this server (system account, no login/password) so the scheduled task can run under its own identity` });
    }

    // 4. PRE-FLIGHT the backing service's execs before the timer can fire it.
    const pf = await preflightUnitExecs({
      host: sshUnitExecHost(conn, onSource),
      unit: tname,
      unitFile: svcUnit,
      existsOnSource: async (p) => (validPath(p) ? shOk(conn, `${onSource(`test -e ${p}`)} >/dev/null 2>&1`, SETUP_TIMEOUT_MS) : false),
      copyFromSource: async (p) => {
        if (!validPath(p) || (await shOk(conn, `test -e ${p}`))) return false;
        const dir = parentDir(p);
        if (!validPath(dir)) return false;
        await sh(conn, `mkdir -p ${dir}`, SETUP_TIMEOUT_MS);
        await execRemote(conn, rsyncPull(p, dir), SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
        return shOk(conn, `test -x ${p}`);
      },
      say: (l) => report(91, "Re-enabling timers…", l),
    });
    for (const fix of pf.repairs) push({ step: `Repair ${tname} before scheduling it`, status: "running", detail: fix });
    if (!pf.ok) {
      unitBlockers.push(...pf.blockers);
      for (const b of pf.blockers) push({ step: `Timer ${tname} was NOT started`, status: "failed", detail: `${b.why}. To finish: ${b.fix}` });
      await report(91, "Re-enabling timers…", `  ${tname}.timer: not started — ${pf.blockers[0].why}.`);
      continue;
    }

    // 5. daemon-reload, then enable the TIMER (not the service — the timer owns
    //    the schedule; systemd starts the service when the timer elapses).
    await execRemote(conn, `systemctl daemon-reload 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
    const en = await execRemote(conn, `systemctl enable --now ${tname}.timer 2>/dev/null`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
    const active = await execRemote(conn, `systemctl is-active ${tname}.timer 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim() === "active").catch(() => false);
    push({
      step: `Timer ${tname}`,
      status: en.code === 0 && active ? "running" : "copied",
      detail:
        en.code === 0 && active
          ? `timer and its task copied, enabled and scheduled — it runs on its own and survives reboots`
          : `timer and its task copied but the schedule is not confirmed active — check: systemctl status ${tname}.timer`,
    });
    await report(91, "Re-enabling timers…", `  ${tname}.timer: ${en.code === 0 && active ? "scheduled" : "copied, verify with systemctl status"}.`);
  }
}

